564	    /// Renders a scene to an image without requiring a window or CAMetalLayer.
565	    ///
566	    /// This is the primary method for headless rendering. It creates an offscreen
567	    /// texture, renders the scene to it, and returns the pixel data as an RGBA image.
568	    #[cfg(any(test, feature = "test-support"))]
569	    pub fn render_scene_to_image(
570	        &mut self,
571	        scene: &Scene,
572	        size: Size<DevicePixels>,
573	    ) -> Result<RgbaImage> {
574	        if size.width.0 <= 0 || size.height.0 <= 0 {
575	            anyhow::bail!("Invalid size for render_scene_to_image: {:?}", size);
576	        }
577	
578	        // Update path intermediate textures for this size
579	        self.update_path_intermediate_textures(size);
580	
581	        // Create an offscreen texture as render target
582	        let texture_descriptor = metal::TextureDescriptor::new();
583	        texture_descriptor.set_width(size.width.0 as u64);
584	        texture_descriptor.set_height(size.height.0 as u64);
585	        texture_descriptor.set_pixel_format(MTLPixelFormat::BGRA8Unorm);
586	        texture_descriptor
587	            .set_usage(metal::MTLTextureUsage::RenderTarget | metal::MTLTextureUsage::ShaderRead);
588	        texture_descriptor.set_storage_mode(metal::MTLStorageMode::Managed);
589	        let target_texture = self.device.new_texture(&texture_descriptor);
590	
591	        let command_buffer = self.render_frame(scene, &target_texture, size)?;
592	
593	        // On discrete GPUs (non-unified memory), Managed textures require an
594	        // explicit blit synchronize before the CPU can read back the rendered
595	        // data. Without this, get_bytes returns stale zeros.
596	        if !self.is_unified_memory {
597	            let blit = command_buffer.new_blit_command_encoder();
598	            blit.synchronize_resource(&target_texture);
599	            blit.end_encoding();
600	        }
601	
602	        // Commit and wait for completion
603	        command_buffer.commit();
604	        command_buffer.wait_until_completed();
605	
606	        read_texture_to_image(&target_texture)
607	    }
